function RecordCards({title,records}:{title:string;records:Data[]}) {return <div className="record-section"><h3>{title}</h3>{records.length?records.map((r,i)=><div className="record-card" key={r.id??i}><Facts data={r}/></div>):<Empty title="未记录"/>}</div>;}
